def fib(n):
    if n < 0:
        raise ValueError("n must be >= 0, got " + str(n))
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a

try:
    print(fib(5))
    print(fib(-1))
except ValueError as e:
    print("Error:", e)

